def minJumps(nums):
    from collections import deque, defaultdict

    n = len(nums)
    if n == 1:
        return 0

    mx = max(nums)
    # smallest prime factor sieve
    spf = list(range(mx + 1))
    i = 2
    while i * i <= mx:
        if spf[i] == i:
            for j in range(i * i, mx + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1

    # groups[p] = indices whose value is divisible by prime p
    groups = defaultdict(list)
    for idx, v in enumerate(nums):
        while v > 1:
            p = spf[v]
            groups[p].append(idx)
            while v % p == 0:
                v //= p

    dist = [-1] * n
    dist[0] = 0
    q = deque([0])
    while q:
        i = q.popleft()
        if i == n - 1:
            return dist[i]
        for j in (i - 1, i + 1):
            if 0 <= j < n and dist[j] < 0:
                dist[j] = dist[i] + 1
                q.append(j)
        p = nums[i]
        if p > 1 and spf[p] == p and p in groups:  # nums[i] is prime
            for j in groups.pop(p):                # use each prime group once
                if dist[j] < 0:
                    dist[j] = dist[i] + 1
                    q.append(j)
    return dist[n - 1]
